import "@stdlib/strings"
import "errors"
import "fees-management"
import "messages"
import "types"

contract ClaimableNftCollection {
    author: "Reza Apes"
    version: "1.0.0"
    description: "Signed entitlement NFT collection implementing TEP-62, TEP-64 and TEP-66"
    storage: ClaimableCollectionStorage
    incomingMessages: AllowedMessageToClaimableCollection
}

type AllowedMessageToClaimableCollection =
    | ClaimMint
    | RequestRoyaltyParams
    | SetMintPrice
    | SetPaused
    | SetTransferFrozen
    | SetTreasury
    | SetVoucherSigner
    | BeginOwnerTransfer
    | AcceptOwnerTransfer
    | CancelOwnerTransfer
    | RequestTransferAuthorization

fun requireOwner(sender: address, owner: address) {
    assert (sender == owner) throw Errors.NotFromOwner;
}

fun requireBasechainAddress(addr: address) {
    assert (addr.getWorkchain() == BASECHAIN) throw Errors.InvalidWorkchain;
}

fun requireValidMaxSupply(maxSupply: uint64) {
    assert (maxSupply > 0 && maxSupply <= MAX_COLLECTION_SUPPLY) throw Errors.MaxSupplyOutOfRange;
}

fun deployNftItem(
    itemIndex: uint64,
    nftItemCode: cell,
    recipient: address,
    individualContent: string,
    serial: uint64,
    nonce: uint256,
) {
    val initParams = NftItemInitAtDeployment {
        ownerAddress: recipient,
        individualContent,
        claimContext: ItemClaimContext {
            serial,
            nonce,
            itemIndex,
            recipientAddress: recipient,
        }.toCell(),
        nextTransferNonce: 0,
        pendingTransfer: null,
    }.toCell();
    val deployMessage = createMessage({
        bounce: BounceMode.RichBounce,
        dest: calcDeployedNftItem(itemIndex, contract.getAddress(), nftItemCode),
        value: NFT_ITEM_DEPLOY_VALUE,
        body: initParams,
    });
    deployMessage.send(SEND_MODE_REGULAR | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
}

fun createIndividualContent(serial: uint64): string {
    var builder = StringBuilder.create();
    builder.appendInt(serial);
    builder.append(".json");
    return builder.build();
}

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessageToClaimableCollection.fromSlice(in.body);

    match (msg) {
        ClaimMint => {
            var storage = ClaimableCollectionStorage.load();
            val immutableConfig = lazy storage.immutableConfig.load();
            val mutableConfig = lazy storage.mutableConfig.load();
            val voucher = lazy msg.voucher.load();
            val nonce = lazy voucher.nonce.load();
            var claimIndexes = storage.claimIndexes.load();

            val claimedLookup = claimIndexes.claimedSerials.get(voucher.serial);
            val failedLookup = claimIndexes.failedClaims.get(voucher.serial);
            val isRetry = claimedLookup.isFound && failedLookup.isFound;

            // Re-check the immutable StateInit value on every claim. This protects the runtime
            // path even if a malformed StateInit was activated without the normal deploy message.
            requireValidMaxSupply(immutableConfig.maxSupply);
            assert (!mutableConfig.paused) throw Errors.CollectionPaused;
            val requiredPayment = isRetry ? RETRY_CLAIM_PAYMENT : mutableConfig.mintPrice;
            assert (in.valueCoins >= requiredPayment) throw Errors.TooLittleValue;
            assert (mutableConfig.mintPrice >= MIN_CLAIM_PRICE) throw Errors.PriceBelowMinimum;
            assert (
                isRetry || storage.nextItemIndex < immutableConfig.maxSupply
            ) throw Errors.SupplyExhausted;
            assert (voucher.serial > 0) throw Errors.InvalidSerial;
            assert (voucher.serial <= immutableConfig.maxSupply) throw Errors.SerialOutOfRange;

            requireBasechainAddress(voucher.recipientAddress);
            assert (in.senderAddress == voucher.recipientAddress) throw Errors.WrongRecipient;
            assert (
                voucher.collectionAddress == contract.getAddress()
            ) throw Errors.WrongCollection;
            assert (
                voucher.voucherDomain == immutableConfig.voucherDomain
            ) throw Errors.WrongVoucherDomain;
            assert (voucher.expiresAt >= blockchain.now() || isRetry) throw Errors.VoucherExpired;
            assert (
                isRetry ||
                isSignatureValid(
                    msg.voucher.hash(),
                    msg.signature as slice,
                    mutableConfig.voucherSignerPublicKey,
                )
            ) throw Errors.InvalidSignature;

            var itemIndex: uint64;
            if (isRetry) {
                val failed = failedLookup.loadValue();
                assert (
                    failed.itemIndex == claimedLookup.loadValue()
                ) throw Errors.SerialAlreadyClaimed;
                assert (failed.nonce == nonce.value) throw Errors.NonceAlreadyUsed;
                assert (
                    failed.recipientAddress == voucher.recipientAddress
                ) throw Errors.WrongRecipient;
                val nonceLookup = claimIndexes.usedNonces.get(nonce.value);
                assert (
                    nonceLookup.isFound && nonceLookup.loadValue() == voucher.serial
                ) throw Errors.NonceAlreadyUsed;
                itemIndex = failed.itemIndex;
                claimIndexes.failedClaims.delete(voucher.serial);
            } else {
                assert (!claimedLookup.isFound) throw Errors.SerialAlreadyClaimed;
                assert (!claimIndexes.usedNonces.exists(nonce.value)) throw Errors.NonceAlreadyUsed;
                itemIndex = storage.nextItemIndex;
                claimIndexes.claimedSerials.set(voucher.serial, itemIndex);
                claimIndexes.usedNonces.set(nonce.value, voucher.serial);
                storage.nextItemIndex += 1;
            }
            storage.claimIndexes = claimIndexes.toCell();
            storage.save();

            reserveToncoinsOnBalance(
                COLLECTION_STORAGE_RESERVE,
                RESERVE_MODE_EXACT_AMOUNT | RESERVE_MODE_BOUNCE_ON_ACTION_FAIL,
            );

            deployNftItem(
                itemIndex,
                immutableConfig.nftItemCode,
                voucher.recipientAddress,
                createIndividualContent(voucher.serial),
                voucher.serial,
                nonce.value,
            );

            val treasuryProceeds = isRetry
                ? (0 as coins)
                : mutableConfig.mintPrice - NFT_ITEM_DEPLOY_VALUE - CLAIM_PROCESSING_BUFFER;
            if (!isRetry && treasuryProceeds > 0) {
                val treasuryMessage = createMessage({
                    bounce: BounceMode.NoBounce,
                    dest: mutableConfig.treasuryAddress,
                    value: treasuryProceeds,
                });
                treasuryMessage.send(SEND_MODE_REGULAR);
            }

            val overpayment = in.valueCoins - requiredPayment;
            if (overpayment > 0) {
                val refundMessage = createMessage({
                    bounce: BounceMode.NoBounce,
                    dest: in.senderAddress,
                    value: overpayment,
                    body: ReturnExcessesBack { queryId: msg.queryId },
                });
                refundMessage.send(SEND_MODE_REGULAR);
            }
        }

        RequestRoyaltyParams => {
            val storage = lazy ClaimableCollectionStorage.load();
            val immutableConfig = lazy storage.immutableConfig.load();
            val response = createMessage({
                bounce: BounceMode.NoBounce,
                dest: in.senderAddress,
                value: 0,
                body: ResponseRoyaltyParams {
                    queryId: msg.queryId,
                    royaltyParams: {
                        numerator: 5,
                        denominator: 100,
                        royaltyAddress: immutableConfig.royaltyAddress,
                    },
                },
            });
            response.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
        }

        SetMintPrice => {
            var storage = ClaimableCollectionStorage.load();
            requireOwner(in.senderAddress, storage.ownerAddress);
            assert (msg.mintPrice >= MIN_CLAIM_PRICE) throw Errors.PriceBelowMinimum;
            var mutableConfig = storage.mutableConfig.load();
            mutableConfig.mintPrice = msg.mintPrice;
            storage.mutableConfig = mutableConfig.toCell();
            storage.save();
        }

        SetPaused => {
            var storage = ClaimableCollectionStorage.load();
            requireOwner(in.senderAddress, storage.ownerAddress);
            var mutableConfig = storage.mutableConfig.load();
            mutableConfig.paused = msg.paused;
            storage.mutableConfig = mutableConfig.toCell();
            storage.save();
        }

        SetTransferFrozen => {
            var storage = ClaimableCollectionStorage.load();
            requireOwner(in.senderAddress, storage.ownerAddress);
            var mutableConfig = storage.mutableConfig.load();
            mutableConfig.transferFrozen = msg.transferFrozen;
            storage.mutableConfig = mutableConfig.toCell();
            storage.save();
        }

        SetTreasury => {
            var storage = ClaimableCollectionStorage.load();
            requireOwner(in.senderAddress, storage.ownerAddress);
            requireBasechainAddress(msg.treasuryAddress);
            var mutableConfig = storage.mutableConfig.load();
            mutableConfig.treasuryAddress = msg.treasuryAddress;
            storage.mutableConfig = mutableConfig.toCell();
            storage.save();
        }

        SetVoucherSigner => {
            var storage = ClaimableCollectionStorage.load();
            requireOwner(in.senderAddress, storage.ownerAddress);
            var mutableConfig = storage.mutableConfig.load();
            mutableConfig.voucherSignerPublicKey = msg.signerPublicKey;
            storage.mutableConfig = mutableConfig.toCell();
            storage.save();
        }

        BeginOwnerTransfer => {
            var storage = ClaimableCollectionStorage.load();
            requireOwner(in.senderAddress, storage.ownerAddress);
            requireBasechainAddress(msg.pendingOwnerAddress);
            var mutableConfig = storage.mutableConfig.load();
            mutableConfig.pendingOwnerAddress = msg.pendingOwnerAddress;
            storage.mutableConfig = mutableConfig.toCell();
            storage.save();
        }

        AcceptOwnerTransfer => {
            var storage = ClaimableCollectionStorage.load();
            var mutableConfig = storage.mutableConfig.load();
            assert (mutableConfig.pendingOwnerAddress != null) throw Errors.PendingOwnerNotSet;
            assert (
                in.senderAddress == mutableConfig.pendingOwnerAddress
            ) throw Errors.NotFromPendingOwner;
            storage.ownerAddress = in.senderAddress;
            mutableConfig.pendingOwnerAddress = null;
            storage.mutableConfig = mutableConfig.toCell();
            storage.save();
        }

        CancelOwnerTransfer => {
            var storage = ClaimableCollectionStorage.load();
            requireOwner(in.senderAddress, storage.ownerAddress);
            var mutableConfig = storage.mutableConfig.load();
            mutableConfig.pendingOwnerAddress = null;
            storage.mutableConfig = mutableConfig.toCell();
            storage.save();
        }

        RequestTransferAuthorization => {
            val storage = lazy ClaimableCollectionStorage.load();
            val immutableConfig = lazy storage.immutableConfig.load();
            val mutableConfig = lazy storage.mutableConfig.load();

            // Only this collection's deterministic, immutable item bytecode may
            // query policy. An arbitrary contract cannot use the collection as
            // an authorization oracle or forge a response for a real item.
            val expectedItemAddress = calcDeployedNftItem(
                msg.itemIndex,
                contract.getAddress(),
                immutableConfig.nftItemCode,
            ).calculateAddress();
            assert (in.senderAddress == expectedItemAddress) throw Errors.WrongCollection;
            assert (msg.itemIndex < storage.nextItemIndex) throw Errors.WrongCollection;
            requireBasechainAddress(msg.currentOwnerAddress);
            requireBasechainAddress(msg.newOwnerAddress);

            var allowed = true;
            if (mutableConfig.transferFrozen) {
                val expectedVaultAddress = calcPersonalVault(
                    msg.currentOwnerAddress,
                    immutableConfig.personalVaultCode,
                ).calculateAddress();
                allowed = msg.newOwnerAddress == expectedVaultAddress;
            }

            assert (in.valueCoins > TRANSFER_POLICY_PROCESSING_BUFFER) throw Errors.TooLittleValue;
            val response = createMessage({
                bounce: BounceMode.RichBounce,
                dest: in.senderAddress,
                value: in.valueCoins - TRANSFER_POLICY_PROCESSING_BUFFER,
                body: TransferAuthorization {
                    authorizationNonce: msg.authorizationNonce,
                    allowed,
                },
            });
            response.send(SEND_MODE_REGULAR | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
        }

        else => {
            assert (in.body.isEmpty()) throw 0xFFFF;
            // The generated deployment wrapper sends an empty body. Reject invalid immutable
            // capacity before the StateInit can be considered a usable collection.
            val storage = ClaimableCollectionStorage.load();
            val immutableConfig = storage.immutableConfig.load();
            requireValidMaxSupply(immutableConfig.maxSupply);
            assert (
                storage.nextItemIndex <= immutableConfig.maxSupply
            ) throw Errors.MaxSupplyOutOfRange;
        }
    }
}

fun onBouncedMessage(in: InMessageBounced) {
    val richBounce = lazy RichBounceBody.fromSlice(in.bouncedBody);
    val bouncedBody = richBounce.originalBody.beginParse();
    val (bouncedBits, bouncedRefs) = bouncedBody.remainingBitsAndRefsCount();
    if (bouncedBits == 97 && bouncedRefs == 0 && bouncedBody.preloadUint(32) == 0x54524152) {
        // A policy response can bounce only from the deterministic item it was
        // addressed to. It carries no collection state transition and the item
        // kept its pending transfer, so safely ignore it rather than attempting
        // to decode it as a bounced item-initialization body.
        return;
    }
    val initParams = lazy NftItemInitAtDeployment.fromCell(richBounce.originalBody);
    val context = lazy initParams.claimContext.load();

    var storage = ClaimableCollectionStorage.load();
    val immutableConfig = storage.immutableConfig.load();
    val expectedItem = calcDeployedNftItem(
        context.itemIndex,
        contract.getAddress(),
        immutableConfig.nftItemCode,
    ).calculateAddress();
    assert (in.senderAddress == expectedItem) throw Errors.WrongCollection;

    var claimIndexes = storage.claimIndexes.load();
    val serialLookup = claimIndexes.claimedSerials.get(context.serial);
    val nonceLookup = claimIndexes.usedNonces.get(context.nonce);
    assert (
        serialLookup.isFound && serialLookup.loadValue() == context.itemIndex
    ) throw Errors.SerialAlreadyClaimed;
    assert (
        nonceLookup.isFound && nonceLookup.loadValue() == context.serial
    ) throw Errors.NonceAlreadyUsed;
    claimIndexes
        .failedClaims
        .set(
            context.serial,
            {
                itemIndex: context.itemIndex,
                nonce: context.nonce,
                recipientAddress: context.recipientAddress,
            },
        );
    storage.claimIndexes = claimIndexes.toCell();
    storage.save();
}

get fun get_collection_data(): CollectionDataReply {
    val storage = lazy ClaimableCollectionStorage.load();
    val immutableConfig = lazy storage.immutableConfig.load();
    return {
        nextItemIndex: storage.nextItemIndex,
        collectionMetadata: immutableConfig.collectionMetadata,
        ownerAddress: storage.ownerAddress,
    };
}

get fun get_nft_address_by_index(itemIndex: int): address {
    val storage = lazy ClaimableCollectionStorage.load();
    val immutableConfig = lazy storage.immutableConfig.load();
    return calcDeployedNftItem(
        itemIndex as uint64,
        contract.getAddress(),
        immutableConfig.nftItemCode,
    ).calculateAddress();
}

get fun get_nft_content(
    _itemIndex: int,
    individualNftContent: string,
): Cell<OffchainMetadataReply> {
    val storage = lazy ClaimableCollectionStorage.load();
    val immutableConfig = lazy storage.immutableConfig.load();
    var builder = StringBuilder.create();
    builder.append(immutableConfig.commonContent);
    builder.append(individualNftContent);
    return OffchainMetadataReply { string: builder.build() }.toCell();
}

get fun royalty_params(): RoyaltyParams {
    val storage = lazy ClaimableCollectionStorage.load();
    val immutableConfig = lazy storage.immutableConfig.load();
    return {
        numerator: 5,
        denominator: 100,
        royaltyAddress: immutableConfig.royaltyAddress,
    };
}

get fun get_claim_config(): ClaimConfigReply {
    val storage = lazy ClaimableCollectionStorage.load();
    val immutableConfig = lazy storage.immutableConfig.load();
    val mutableConfig = lazy storage.mutableConfig.load();
    return {
        ownerAddress: storage.ownerAddress,
        pendingOwnerAddress: mutableConfig.pendingOwnerAddress,
        nextItemIndex: storage.nextItemIndex,
        maxSupply: immutableConfig.maxSupply,
        mintPrice: mutableConfig.mintPrice,
        minimumMintPrice: MIN_CLAIM_PRICE,
        paused: mutableConfig.paused,
        transferFrozen: mutableConfig.transferFrozen,
        treasuryAddress: mutableConfig.treasuryAddress,
        voucherSignerPublicKey: mutableConfig.voucherSignerPublicKey,
        voucherDomain: immutableConfig.voucherDomain,
        royaltyAddress: immutableConfig.royaltyAddress,
    };
}

get fun get_claimed_item_index(serial: uint64): ClaimLookupReply {
    val storage = ClaimableCollectionStorage.load();
    val claimIndexes = storage.claimIndexes.load();
    val lookup = claimIndexes.claimedSerials.get(serial);
    if (!lookup.isFound) {
        return { claimed: false, itemIndex: 0 };
    }
    return { claimed: true, itemIndex: lookup.loadValue() };
}

get fun is_nonce_used(nonce: uint256): bool {
    val storage = ClaimableCollectionStorage.load();
    val claimIndexes = storage.claimIndexes.load();
    return claimIndexes.usedNonces.exists(nonce);
}

get fun is_claim_retryable(serial: uint64): bool {
    val storage = ClaimableCollectionStorage.load();
    val claimIndexes = storage.claimIndexes.load();
    return claimIndexes.failedClaims.exists(serial);
}

/// Compile-time on-chain ceiling used by deployment tooling and verification.
get fun get_max_collection_supply(): uint64 {
    return MAX_COLLECTION_SUPPLY as uint64;
}

/// The NFT item keeps this amount after each transfer, matching the reference TEP-62 item.
const NFT_ITEM_STORAGE_RESERVE = ton("0.05")

/// Hard on-chain limit for the three persistent claim dictionaries. This is intentionally
/// conservative relative to TON's account-state cell limits and must not be raised without a
/// fresh state-growth analysis and independent audit.
const MAX_COLLECTION_SUPPLY = 8000

/// Signup Ape uses deterministic item indexes and stores no per-claim dictionaries in the
/// collection account. Its capacity is therefore a business limit rather than an account-state
/// growth limit. Keep this separate from MAX_COLLECTION_SUPPLY: the paid collection bytecode must
/// never inherit this larger ceiling.
const MAX_SIGNUP_COLLECTION_SUPPLY = 1000000

/// Each new item receives enough value to initialize and retain its storage reserve in local tests.
const NFT_ITEM_DEPLOY_VALUE = ton("0.08")

/// Minimum collection balance protected while processing a claim. There is deliberately no
/// owner sweep: processing buffers remain in the collection until audited dynamic rent economics
/// are available.
const COLLECTION_STORAGE_RESERVE = ton("0.10")

/// Amount left from each mint payment for compute/action fees and growing storage rent.
const CLAIM_PROCESSING_BUFFER = ton("0.07")

/// Owner cannot set a lower claim price. Re-evaluate after any code or network fee change.
const MIN_CLAIM_PRICE = NFT_ITEM_DEPLOY_VALUE + CLAIM_PROCESSING_BUFFER

/// Every TEP-62 transfer performs an authenticated item -> collection -> item
/// policy round trip so a freeze toggle applies immediately to already-minted
/// NFTs. The item sends a fixed, bounded amount; the collection returns the
/// remainder and never uses carry-all mode (which could sweep collection rent
/// reserves or accumulated claim buffers).
const TRANSFER_POLICY_REQUEST_VALUE = ton("0.05")
const TRANSFER_POLICY_PROCESSING_BUFFER = ton("0.02")
const TRANSFER_POLICY_COMPLETION_BUFFER = ton("0.005")
const MIN_NFT_TRANSFER_VALUE = ton("0.065")

/// A bounced item deployment already returned its deploy value to the collection.
/// A retry only supplies a fresh compute/action budget and never pays treasury again.
const RETRY_CLAIM_PAYMENT = CLAIM_PROCESSING_BUFFER

/// Personal vault storage reserve and withdrawal transaction budget.
const VAULT_STORAGE_RESERVE = ton("0.05")
const VAULT_PROCESSING_BUFFER = ton("0.03")
const MIN_VAULT_WITHDRAW_VALUE = ton("0.10")

import "types"

/// Parameters sent by a collection to initialize a deterministic NFT item.
struct NftItemInitAtDeployment {
    ownerAddress: address
    individualContent: string
    claimContext: Cell<ItemClaimContext>
    nextTransferNonce: uint64
    pendingTransfer: Cell<PendingNftTransfer>?
}

/// Context returned intact in a rich bounce if item initialization fails.
struct ItemClaimContext {
    serial: uint64
    nonce: uint256
    itemIndex: uint64
    recipientAddress: address
}

// TEP-66 royalty request and response.
struct (0x693d3950) RequestRoyaltyParams {
    queryId: uint64
}

struct (0xa8cb00ad) ResponseRoyaltyParams {
    queryId: uint64
    royaltyParams: RoyaltyParams
}

/// Domain-separated voucher signed by the backend Ed25519 key.
///
/// `collectionAddress` and `voucherDomain` prevent a valid voucher from being
/// replayed on another collection or network deployment. Sign the raw 32-byte
/// representation hash of this cell; see the checked golden vector.
struct (0x41504556) ClaimVoucher {
    voucherDomain: uint256
    collectionAddress: address
    serial: uint64
    recipientAddress: address
    expiresAt: uint32
    nonce: Cell<ClaimNonce>
}

/// A full-width nonce kept in a reference so ClaimVoucher stays within one cell.
/// `value` is exactly 32 big-endian bytes on the wire.
struct ClaimNonce {
    value: uint256
}

/// Claim an entitled Ape. The signature is Ed25519 over the raw 32-byte
/// representation hash of `voucher`; see `docs/ABI.md`.
struct (0x6d1e7851) ClaimMint {
    queryId: uint64
    voucher: Cell<ClaimVoucher>
    signature: bits512
}

/// Signup vouchers additionally bind the immutable legacy artwork identifier. Many signup NFTs
/// intentionally share one catalog image, so item metadata is stored once as `nft-<id>.json`.
struct (0x53554756) SignupClaimVoucher {
    voucherDomain: uint256
    collectionAddress: address
    serial: uint64
    contentId: uint64
    recipientAddress: address
    expiresAt: uint32
    nonce: Cell<ClaimNonce>
}

struct (0x53554743) ClaimSignupMint {
    queryId: uint64
    voucher: Cell<SignupClaimVoucher>
    signature: bits512
}

struct (0x4d8d2f40) SetMintPrice {
    queryId: uint64
    mintPrice: coins
}

struct (0x65c0e6f7) SetPaused {
    queryId: uint64
    paused: bool
}

/// Toggle collection-wide transfer policy without pausing minting. New
/// collections start frozen. While frozen, canonical NFT items are authorized
/// to move only into the deterministic personal vault of their current owner.
struct (0x65f2ec04) SetTransferFrozen {
    queryId: uint64
    transferFrozen: bool
}

struct (0x21a196a4) SetTreasury {
    queryId: uint64
    treasuryAddress: address
}

struct (0x7f6a5c45) SetVoucherSigner {
    queryId: uint64
    signerPublicKey: uint256
}

struct (0x2c655d8e) BeginOwnerTransfer {
    queryId: uint64
    pendingOwnerAddress: address
}

struct (0x79f2d8ac) AcceptOwnerTransfer {
    queryId: uint64
}

struct (0x19df9f21) CancelOwnerTransfer {
    queryId: uint64
}

// TEP-62 item messages.
struct (0x2fcb26a2) RequestStaticData {
    queryId: uint64
}

struct (0x8b771735) ResponseStaticData {
    queryId: uint64
    itemIndex: uint256
    collectionAddress: address
}

struct (0b0) PayloadInline {
    value: RemainingBitsAndRefs
}

struct (0b1) PayloadInRef {
    value: Cell<RemainingBitsAndRefs>
}

struct (0x05138d91) NotificationForNewOwner {
    queryId: uint64
    oldOwnerAddress: address
    @abi.clientType(PayloadInline | PayloadInRef)
    payload: RemainingBitsAndRefs
}

struct (0xd53276db) ReturnExcessesBack {
    queryId: uint64
}

struct (0x5fcc3d14) AskToChangeOwnership {
    queryId: uint64
    newOwnerAddress: address
    sendExcessesTo: address?
    customPayload: cell?
    forwardTonAmount: coins
    @abi.clientType(PayloadInline | PayloadInRef)
    forwardPayload: RemainingBitsAndRefs
}

/// Canonical item -> collection transfer-policy request. The collection
/// authenticates the deterministic item address from `itemIndex` before it
/// replies. The monotonically increasing nonce binds the reply to one pending
/// transfer and prevents delayed/replayed approvals.
struct (0x54524151) RequestTransferAuthorization {
    authorizationNonce: uint64
    itemIndex: uint64
    currentOwnerAddress: address
    newOwnerAddress: address
}

/// Canonical collection -> item policy decision.
struct (0x54524152) TransferAuthorization {
    authorizationNonce: uint64
    allowed: bool
}

/// Deploy/activate a deterministic personal vault. It is intentionally a no-op
/// after authenticating the immutable owner.
struct (0x5641554c) DeployPersonalVault {
    queryId: uint64
}

/// Withdraw an NFT only to the vault's immutable original wallet.
struct (0x0f8a7ea5) WithdrawNftToOwner {
    queryId: uint64
    nftItemAddress: address
}

struct RoyaltyParams {
    numerator: uint16
    denominator: uint16
    royaltyAddress: address
}

/// Values that are never modified after StateInit.
struct CollectionImmutableConfig {
    maxSupply: uint64
    voucherDomain: uint256
    royaltyAddress: address
    collectionMetadata: cell
    commonContent: string
    nftItemCode: cell
    personalVaultCode: cell
}

/// Owner-controlled collection settings.
struct CollectionMutableConfig {
    mintPrice: coins
    paused: bool
    transferFrozen: bool
    treasuryAddress: address
    voucherSignerPublicKey: uint256
    pendingOwnerAddress: address?
}

/// A claim that reached asynchronous item deployment but bounced. Retaining the
/// original index permits an exact retry without creating a marketplace index gap.
struct FailedClaimRecord {
    itemIndex: uint64
    nonce: uint256
    recipientAddress: address
}

struct ClaimIndexes {
    claimedSerials: map<uint64, uint64>
    usedNonces: map<uint256, uint64>
    failedClaims: map<uint64, FailedClaimRecord>
}

/// Root is intentionally four references or fewer.
struct ClaimableCollectionStorage {
    ownerAddress: address
    nextItemIndex: uint64
    immutableConfig: Cell<CollectionImmutableConfig>
    mutableConfig: Cell<CollectionMutableConfig>
    claimIndexes: Cell<ClaimIndexes>
}

/// Constant-size storage for Signup Ape. Claim replay protection is provided by the deterministic
/// item address `serial - 1`: an initialized NFT item rejects every later initialization message.
/// Keeping claim dictionaries out of this account is what permits a six-figure collection.
struct ScalableSignupCollectionStorage {
    ownerAddress: address
    immutableConfig: Cell<CollectionImmutableConfig>
    mutableConfig: Cell<CollectionMutableConfig>
}

struct NftItemStorage {
    itemIndex: uint64
    collectionAddress: address
    ownerAddress: address
    individualContent: string
    nextTransferNonce: uint64
    pendingTransfer: Cell<PendingNftTransfer>?
}

/// A standard TEP-62 transfer retained while the canonical collection makes
/// the current, collection-wide transfer-policy decision. The item accepts at
/// most one pending transfer and binds the reply to a monotonic nonce.
struct PendingNftTransfer {
    authorizationNonce: uint64
    originalOwnerAddress: address
    transferBody: cell
}

struct NftItemStorageNotInitialized {
    itemIndex: uint64
    collectionAddress: address
}

struct NftItemStorageLoader {
    itemIndex: uint64
    collectionAddress: address
    private rest: RemainingBitsAndRefs
}

struct PersonalVaultStorage {
    ownerAddress: address
}

struct CollectionDataReply {
    nextItemIndex: int
    collectionMetadata: cell
    ownerAddress: address
}

struct NftDataReply {
    isInitialized: bool
    itemIndex: int
    collectionAddress: address
    ownerAddress: address? = null
    individualContent: string? = null
}

struct ClaimConfigReply {
    ownerAddress: address
    pendingOwnerAddress: address?
    nextItemIndex: uint64
    maxSupply: uint64
    mintPrice: coins
    minimumMintPrice: coins
    paused: bool
    transferFrozen: bool
    treasuryAddress: address
    voucherSignerPublicKey: uint256
    voucherDomain: uint256
    royaltyAddress: address
}

struct ClaimLookupReply {
    claimed: bool
    itemIndex: uint64
}

struct (0x01) OffchainMetadataReply {
    string: string
}

fun ClaimableCollectionStorage.load(): ClaimableCollectionStorage {
    return ClaimableCollectionStorage.fromCell(contract.getData());
}

fun ClaimableCollectionStorage.save(self) {
    contract.setData(self.toCell());
}

fun ScalableSignupCollectionStorage.load(): ScalableSignupCollectionStorage {
    return ScalableSignupCollectionStorage.fromCell(contract.getData());
}

fun ScalableSignupCollectionStorage.save(self) {
    contract.setData(self.toCell());
}

fun ClaimIndexes.empty(): ClaimIndexes {
    return {
        claimedSerials: [],
        usedNonces: [],
        failedClaims: [],
    };
}

fun NftItemStorage.startLoading(): NftItemStorageLoader {
    return NftItemStorageLoader.fromCell(contract.getData());
}

fun NftItemStorage.save(self) {
    contract.setData(self.toCell());
}

fun NftItemStorageLoader.isNotInitialized(self): bool {
    return self.rest.isEmpty();
}

fun NftItemStorageLoader.endLoading(mutate self): NftItemStorage {
    return {
        itemIndex: self.itemIndex,
        collectionAddress: self.collectionAddress,
        ownerAddress: self.rest.loadAny(),
        individualContent: self.rest.loadAny(),
        nextTransferNonce: self.rest.loadAny(),
        pendingTransfer: self.rest.loadAny(),
    };
}

fun calcPersonalVault(ownerAddress: address, personalVaultCode: cell): AutoDeployAddress {
    val initialStorage: PersonalVaultStorage = { ownerAddress };
    return { stateInit: { code: personalVaultCode, data: initialStorage.toCell() } };
}

fun PersonalVaultStorage.load(): PersonalVaultStorage {
    return PersonalVaultStorage.fromCell(contract.getData());
}

fun calcDeployedNftItem(
    itemIndex: uint64,
    collectionAddress: address,
    nftItemCode: cell,
): AutoDeployAddress {
    val initialStorage: NftItemStorageNotInitialized = { itemIndex, collectionAddress };
    return { stateInit: { code: nftItemCode, data: initialStorage.toCell() } };
}
